package com.stockpilot.security.controller;
import com.stockpilot.common.api.ApiResponse;import com.stockpilot.security.application.AuthenticationApplicationService;import com.stockpilot.security.request.SecurityRequests;import com.stockpilot.security.vo.SecurityVO;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthenticationController {private final AuthenticationApplicationService service;public AuthenticationController(AuthenticationApplicationService s){service=s;}@PostMapping("/login")public ApiResponse<SecurityVO.Token> login(@Valid @RequestBody SecurityRequests.Login r){return ApiResponse.success(service.login(r));}}
